import fs from 'node:fs';

const endpoint = 'http://127.0.0.1:9333';
const targetList = await (await fetch(`${endpoint}/json/list`)).json();
const page = targetList.find((t) => t.type === 'page');
if (!page) throw new Error('No page target');

const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve, { once: true });
  ws.addEventListener('error', reject, { once: true });
});

let id = 0;
const pending = new Map();
ws.addEventListener('message', (event) => {
  const message = JSON.parse(event.data);
  if (message.id && pending.has(message.id)) {
    const { resolve, reject } = pending.get(message.id);
    pending.delete(message.id);
    if (message.error) reject(new Error(JSON.stringify(message.error)));
    else resolve(message.result);
  }
});

function send(method, params = {}) {
  id += 1;
  const callId = id;
  return new Promise((resolve, reject) => {
    pending.set(callId, { resolve, reject });
    ws.send(JSON.stringify({ id: callId, method, params }));
  });
}

await send('Page.enable');
await send('Runtime.enable');
await send('Emulation.setDeviceMetricsOverride', {
  width: 390,
  height: 1400,
  deviceScaleFactor: 1,
  mobile: true,
});
await send('Page.navigate', {
  url: 'file:///<WORKSPACE>/landing/index.html',
});
await new Promise((resolve) => setTimeout(resolve, 1800));

const metrics = await send('Runtime.evaluate', {
  expression: `JSON.stringify({
    innerWidth: window.innerWidth,
    documentScrollWidth: document.documentElement.scrollWidth,
    bodyScrollWidth: document.body.scrollWidth,
    bodyClientWidth: document.body.clientWidth,
    h1Width: document.querySelector('h1').getBoundingClientRect().width,
    h1Height: document.querySelector('h1').getBoundingClientRect().height,
    plateWidth: document.querySelector('.plate').getBoundingClientRect().width,
    canvasRight: document.querySelector('.canvas').getBoundingClientRect().right,
    factsColumns: getComputedStyle(document.querySelector('.facts-grid')).gridTemplateColumns
  })`,
  returnByValue: true,
});
console.log(metrics.result.value);

const shot = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
fs.writeFileSync('tmp/cdp-390-top.png', Buffer.from(shot.data, 'base64'));

await send('Runtime.evaluate', { expression: 'window.scrollTo(0, 900)' });
await new Promise((resolve) => setTimeout(resolve, 300));
const shot2 = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
fs.writeFileSync('tmp/cdp-390-mid.png', Buffer.from(shot2.data, 'base64'));

ws.close();


